// n8n Code node "Build request" (Run Once for All Items).
//
// Receives the context the app sends (the agent never reads the database) and
// builds the Claude request. The reply format is FIXED here, in code, not in
// the editable instructions: editing the instructions in the panel can change
// the tone, never the contract the code checks afterwards.
const body = ($input.first().json || {}).body || {};

function text(v, max) {
  return typeof v === 'string' ? v.slice(0, max) : '';
}

const instructions = text(body.instructions, 20000);
const message = text(body.message, 2000).trim();
const facts = Array.isArray(body.facts) ? body.facts.slice(0, 200) : [];
const history = Array.isArray(body.history) ? body.history.slice(-10) : [];

if (!instructions || !message) {
  throw new Error('invalid_input: instructions and message are required');
}

// Only facts the app marked as approved arrive here. Each one has a short code
// the model must cite; the next node checks every code against this list.
const approvedCodes = [];
const factLines = [];
for (const f of facts) {
  const code = text(f && f.code, 10);
  const content = text(f && f.content, 2000);
  if (!/^F\d{2,3}$/.test(code) || !content) continue;
  approvedCodes.push(code);
  factLines.push(`[${code}] ${text(f.title, 200)}: ${content}`);
}

const ROLE = { visitor: 'Visitor', agent: 'Assistant', staff: 'Harbour staff' };
const transcript = history
  .filter((m) => m && ROLE[m.role])
  .map((m) => `${ROLE[m.role]}: ${text(m.content, 2000)}`)
  .join('\n');

const rules = [
  '## Approved facts',
  'These are the ONLY things you may state as true about Harbour Study Abroad.',
  'Cite the code of every fact you use in fact_codes. If no fact answers the',
  'question, set knew to false and do not guess. Greetings and small talk need',
  'no fact.',
  '',
  factLines.join('\n') || '(no approved facts)',
].join('\n');

// The reply format, enforced by the API (structured outputs): the response is
// always valid JSON matching this schema. (Forced tool_choice is rejected by
// Claude Sonnet 5.5, so structured outputs is the supported way to get it.)
const replySchema = {
  type: 'object',
  properties: {
    reply: { type: 'string', description: 'The message shown to the visitor.' },
    knew: {
      type: 'boolean',
      description: 'true only if the approved facts answer the question (or it is a greeting). false if a person must answer.',
    },
    fact_codes: {
      type: 'array',
      items: { type: 'string' },
      description: 'Codes of the approved facts used, e.g. ["F07"]. Empty for greetings.',
    },
    needs_human: {
      type: 'boolean',
      description: 'true if a consultant must take over (unknown answer, quote, booking, complaint, asked for a person).',
    },
    reason: { type: 'string', description: 'Short internal note for the team when needs_human is true, otherwise empty.' },
  },
  required: ['reply', 'knew', 'fact_codes', 'needs_human', 'reason'],
  additionalProperties: false,
};

const payload = {
  // "Simulate AI failure" in the panel sends a model that does not exist, so the
  // demo exercises the REAL error path of the workflow, not a fake one.
  model: body.simulate_failure === true ? 'harbour-simulated-failure' : 'claude-sonnet-5-5',
  max_tokens: 4096,  // room for adaptive thinking + the short JSON reply
  system: [
    { type: 'text', text: instructions, cache_control: { type: 'ephemeral' } },
    { type: 'text', text: rules, cache_control: { type: 'ephemeral' } },
  ],
  messages: [
    {
      role: 'user',
      content:
        (transcript ? `Conversation so far:\n${transcript}\n\n` : '') +
        `New message from the visitor:\n<visitor_message>\n${message}\n</visitor_message>`,
    },
  ],
  // low effort: short support replies from a fixed fact list, latency matters
  output_config: { effort: 'low', format: { type: 'json_schema', schema: replySchema } },
};

return [{ json: { payload, approved_codes: approvedCodes } }];

// n8n Code node "Check answer" (Run Once for All Items).
//
// The model's word is not trusted. This node checks the reply in code before it
// can reach the visitor:
//   1. the reply must come in the fixed format;
//   2. every fact it cites must be one of the approved facts sent in;
//   3. a deterministic guard blocks prices, money amounts and exact dates,
//      whatever the instructions say.
// Anything that fails becomes a hand-over to a person, never a guess.
const resp = $input.first().json || {};
const approved = new Set($('Build request').first().json.approved_codes || []);

// Structured output: the answer is the JSON in the text block.
let a = null;
try {
  const txt = (resp.content || []).filter((b) => b && b.type === 'text').map((b) => b.text).join('');
  a = JSON.parse(txt);
} catch (e) {
  a = null;
}
if (resp.stop_reason === 'refusal' || resp.stop_reason === 'max_tokens') a = null;

if (!a || typeof a.reply !== 'string' || !a.reply.trim() || typeof a.knew !== 'boolean') {
  return [{ json: { ok: false, error: 'invalid_output', detail: 'The model did not return the expected format.' } }];
}

const cited = Array.isArray(a.fact_codes) ? a.fact_codes.map(String) : [];
const unknown = cited.filter((c) => !approved.has(c));

function guard(t) {
  const rules = [
    [/(A\$|AU\$|NZ\$|US\$|R\$|\$|€|£)\s?\d/i, 'price'],
    [/\b(AUD|NZD|USD|BRL|EUR|GBP|CAD)\s?\d/i, 'price'],
    [/\d[\d,.]*\s?(dollars?|reais|euros?|pounds?)\b/i, 'price'],
    [/\b\d{1,3}\s?%\s?(off|discount|scholarship)/i, 'discount'],
    [/\b\d{1,2}\/\d{1,2}(\/\d{2,4})?\b/, 'exact date'],
  ];
  for (const [re, why] of rules) if (re.test(t)) return why;
  return null;
}

const blocked = guard(a.reply);
let reply = a.reply.trim();
let knew = a.knew;
let needsHuman = a.needs_human === true || a.knew === false;
let reason = typeof a.reason === 'string' ? a.reason.slice(0, 300) : '';
let guardrail = null;

if (unknown.length) {
  // cited something that is not an approved fact: do not send it
  guardrail = `unapproved fact cited: ${unknown.join(', ')}`;
  knew = false;
  needsHuman = true;
  reply = '';
} else if (blocked) {
  guardrail = blocked;
  needsHuman = true;
  reply = 'I can not share prices, discounts or exact dates here, so a consultant will send you the right details in this chat.';
}

if (needsHuman && !reason) reason = guardrail ? `Guardrail: ${guardrail}` : 'The approved facts do not answer this question.';

return [{
  json: {
    ok: true,
    reply,            // empty = the app uses the hand-over message from settings
    knew,
    fact_codes: unknown.length ? [] : cited,
    needs_human: needsHuman,
    reason,
    guardrail,
    usage: resp.usage || null,
  },
}];

// n8n Code node "Describe failure" (Run Once for All Items).
// The Claude call failed (bad key, no credit, timeout, invalid request...).
// The workflow still answers the app, with ok:false, so the app can send the
// fallback message to the visitor and raise the alert in the panel.
// n8n puts the generic text in error.message and the API's own explanation in
// error.description: keep both so the panel shows the real cause.
const j = $input.first().json || {};
const err = j.error || {};
const parts = [err.message, err.description].filter((x) => typeof x === 'string' && x.trim());
const detail = (parts.join(' | ') || JSON.stringify(err) || 'unknown error').slice(0, 500);
return [{ json: { ok: false, error: 'ai_error', detail } }];
